        return random.choice(["2.5", "0.5", "3.0", ".5"])
    if r < 0.75:
        return "(" + expr(env, 1) + ")"
    if r < 0.85:
        return random.choice(["+", "-"]) + atom(env)
    return random.choice(list(env))

def expr(env, depth=0):
    left = atom(env)
    for _ in range(random.randint(0, 2 if depth else 3)):
        op = random.choice(ops)
        right = atom(env)
        # Avoid floor/mod by zero and 0 ** negative producing surprises.
        if op in ("/", "//", "%"):
            right = "(" + right + " + 1000)"
        if op == "**":
            right = str(random.randint(0, 3))
        left = left + " " + op + " " + right
    return left

